from research_helpers import *
a=ev('https://ontoinnovation.com/writable/files/RudolphTechnologiesInc10K12.31.16-FINAL.pdf','Historical annual product table: exact instrument families. Legacy availability unresolved.')
b=ev('https://ontoinnovation.com/writable/files/Resources/RTEC-Investor-Presentation-V290818.pdf','Historical issuer presentation names Firefly, Dragonfly, AWX, Discover and Equipment Sentinel. Indexed primary content reviewed; direct PDF rendering unavailable.')
c=ev('https://investors.ontoinnovation.com/news/news-details/2015/Rudolph-Technologies-Reports-2015-Third-Quarter-Results/default.aspx','Issuer confirms NSX 330 adoption and JetStep W2300 customer order; historical order not current offering.')
d=ev('https://investors.ontoinnovation.com/news/news-details/2019/Onto-Innovation-Reports-Third-Quarter-2019-Results-Combined-Company-Guidance-and-Additional-Merger-Details/default.aspx','October 25 2019 merger: Rudolph survives as wholly owned Nanometrics subsidiary; parent renamed Onto. Not every combined-company product attributed to Rudolph.')
products=[]
for name,desc in [('MetaPULSE','Opaque thin-film metrology family.'),('NSX Inspection System','Wafer/die/bump inspection family.'),('PrecisionWoRx','Probe-card analysis system.'),('Reflex TT','Manual bare-wafer inspection system.'),('Reflex TT MBI','Mask inspection system.'),('S3000','Transparent thin-film metrology system.'),('SONUS','Acoustic film metrology/defect inspection system.'),('Wafer Scanner','Bump inspection system.'),('JetStep W','Wafer packaging lithography system.'),('JetStep S','Panel packaging lithography system.')]:products.append(p(name,desc,a,typ='product',sector='semiconductors',sub='semiconductor_equipment',evidence=[a,d]))
for name,desc in [('Firefly','Semiconductor inspection system family.'),('Dragonfly','Combined semiconductor inspection/metrology system.'),('AWX','Wafer inspection system family.'),('Discover','Semiconductor yield-management software.'),('Equipment Sentinel','Semiconductor process-control software.')]:products.append(p(name,desc,b,typ='product',sector='semiconductors',sub='semiconductor_equipment',evidence=[b,d]))
for name,desc in [('NSX 330','Semiconductor packaging inspection/metrology system.'),('JetStep W2300','Advanced packaging lithography model.')]:products.append(p(name,desc,c,typ='product',sector='semiconductors',sub='semiconductor_equipment',evidence=[c,d]))
co=dict(company_id='cmp_296dd733-3bfe-4b72-a233-780669f33e91',products=products,evidence=[a,b,c,d],status='partial',coverage_note='Seventeen historical Rudolph system/model/software identities, current lifecycle unresolved. Specific NSX330/JetStepW2300 coexist with umbrella families without implying additional unique technology counts. Standalone display-only G35/G45 steppers excluded absent target-sector application. Partial: remaining model generations, current availability and post-merger legal-entity development/manufacturing roles remain. Nanometrics/Onto products not automatically attributed to Rudolph.')
(out/'batch-0346.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
